SELECT?course
WHERE {
  ?course a ns1:course.
  ?course ns1:has_research_group ns1:computer_system_laboratory.
}

SELECT?course
WHERE {
  ?course ns1:has_evaluation_method ns1:project.
  ?course ns1:has_evaluation_method ns1:lab_assignment.
  ?course ns1:has_course_code "CSCE604133".
}

SELECT?course
WHERE {
  ?course a ns1:course.
  ?course ns1:has_evaluation_method ns1:test.
}

SELECT DISTINCT?course
WHERE {
  ns1:internet_of_things ns1:has_prerequisite_course?prereq.
  ?course ns1:has_prerequisite_course?prereq.
  FILTER (?course != ns1:internet_of_things)
}

SELECT (count(?course) as?count)
WHERE {
  ?course a ns1:course.
  ?course ns1:has_course_category ns1:study_program_elective_course.
}

